const menu=document.querySelector('#menu');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('#navigation').classList.toggle('open',open)});document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=button.dataset.filter!=='All'&&card.dataset.category!==button.dataset.filter;if(!card.hidden)count++});document.querySelector('#results').textContent=count+' projects'}));document.querySelector('#year').textContent=new Date().getFullYear();if(matchMedia('(pointer:fine) and (prefers-reduced-motion:no-preference)').matches){const scene=document.querySelector('.scene'),card=document.querySelector('.tilt');scene?.addEventListener('pointermove',e=>{const r=scene.getBoundingClientRect();card.style.transform=`rotateY(${(e.clientX-r.left)/r.width*20-20}deg) rotateX(${10-(e.clientY-r.top)/r.height*15}deg) rotateZ(-4deg)`});scene?.addEventListener('pointerleave',()=>card.style.transform='');}